insert into public.together_world_facts(id,world_id,slug,title,fact_text,category,truth_mode,knowledge_scope,content_level,location_id,district_location_id,topic_tags,trigger_terms,active,metadata) select id,world_id,slug,title,fact_text,category,truth_mode,knowledge_scope,content_level,location_id,district_location_id,topic_tags,trigger_terms,active,metadata from jsonb_to_recordset('[{"id":"2873dcbb-5c07-57af-b54e-79806be121cc","world_id":"31740169-035e-5b10-8c9d-98b206e9f24b","slug":"calders-2873dcbb-5c07-57af-b54e-79806be121cc","title":"Main Street: district","fact_text":"Permanent brick arrived after the first silver profits. Shopkeepers widened the boardwalks while moving older stalls downhill. The courthouse occupies an expanded reading-room building, and its piecemeal construction is visible from the alley.","category":"history","truth_mode":"canonical","knowledge_scope":"local","content_level":"standard","location_id":"8ea973d5-94fe-5c5c-8cb3-84a90abef76e","district_location_id":"8ea973d5-94fe-5c5c-8cb3-84a90abef76e","topic_tags":["main-street","district"],"trigger_terms":["Main Street"],"active":true,"metadata":{"source":"calders_run_authoring_v1","authoringFactId":"2873dcbb-5c07-57af-b54e-79806be121cc","requiresSavedDisclosure":false,"characterSlugs":[],"revealGate":null,"partialKnowledge":[]}},{"id":"3f3bb467-b257-59be-a080-f2dd65dc3ac2","world_id":"31740169-035e-5b10-8c9d-98b206e9f24b","slug":"calders-3f3bb467-b257-59be-a080-f2dd65dc3ac2","title":"Main Street: district","fact_text":"Freight and shopping dominate morning; court business and repairs fill afternoon; hotel balconies and supper visits soften the evening.","category":"history","truth_mode":"canonical","knowledge_scope":"local","content_level":"standard","location_id":"8ea973d5-94fe-5c5c-8cb3-84a90abef76e","district_location_id":"8ea973d5-94fe-5c5c-8cb3-84a90abef76e","topic_tags":["main-street","district"],"trigger_terms":["Main Street"],"active":true,"metadata":{"source":"calders_run_authoring_v1","authoringFactId":"3f3bb467-b257-59be-a080-f2dd65dc3ac2","requiresSavedDisclosure":false,"characterSlugs":[],"revealGate":null,"partialKnowledge":[]}},{"id":"0b98de05-c1e0-5c4c-8711-895a586da3b4","world_id":"31740169-035e-5b10-8c9d-98b206e9f24b","slug":"calders-0b98de05-c1e0-5c4c-8711-895a586da3b4","title":"Main Street: district","fact_text":"Shop staff exchange small change and errands before the first coach arrival.","category":"history","truth_mode":"canonical","knowledge_scope":"local","content_level":"standard","location_id":"8ea973d5-94fe-5c5c-8cb3-84a90abef76e","district_location_id":"8ea973d5-94fe-5c5c-8cb3-84a90abef76e","topic_tags":["main-street","district"],"trigger_terms":["Main Street"],"active":true,"metadata":{"source":"calders_run_authoring_v1","authoringFactId":"0b98de05-c1e0-5c4c-8711-895a586da3b4","requiresSavedDisclosure":false,"characterSlugs":[],"revealGate":null,"partialKnowledge":[]}},{"id":"1734dc69-22db-5835-a433-84f7be2383c9","world_id":"31740169-035e-5b10-8c9d-98b206e9f24b","slug":"calders-1734dc69-22db-5835-a433-84f7be2383c9","title":"Lantern Row: district","fact_text":"Temporary drinking rooms gave way to purpose-built businesses when miners began receiving regular pay. Adult establishments and theaters funded improvements that more respectable neighbors also use.","category":"history","truth_mode":"canonical","knowledge_scope":"local","content_level":"standard","location_id":"604a7a05-0d7e-5ea2-9357-1e9953bf3bd1","district_location_id":"604a7a05-0d7e-5ea2-9357-1e9953bf3bd1","topic_tags":["lantern-row","district"],"trigger_terms":["Lantern Row"],"active":true,"metadata":{"source":"calders_run_authoring_v1","authoringFactId":"1734dc69-22db-5835-a433-84f7be2383c9","requiresSavedDisclosure":false,"characterSlugs":[],"revealGate":null,"partialKnowledge":[]}},{"id":"76fc033b-dfb1-52d4-a7da-cf3d95221cb9","world_id":"31740169-035e-5b10-8c9d-98b206e9f24b","slug":"calders-76fc033b-dfb1-52d4-a7da-cf3d95221cb9","title":"Lantern Row: district","fact_text":"Late mornings belong to staff and deliveries. Rehearsal and preparation grow into crowded evenings; closing-time meals create their own community.","category":"history","truth_mode":"canonical","knowledge_scope":"local","content_level":"standard","location_id":"604a7a05-0d7e-5ea2-9357-1e9953bf3bd1","district_location_id":"604a7a05-0d7e-5ea2-9357-1e9953bf3bd1","topic_tags":["lantern-row","district"],"trigger_terms":["Lantern Row"],"active":true,"metadata":{"source":"calders_run_authoring_v1","authoringFactId":"76fc033b-dfb1-52d4-a7da-cf3d95221cb9","requiresSavedDisclosure":false,"characterSlugs":[],"revealGate":null,"partialKnowledge":[]}},{"id":"ac6ebc71-dae7-53f1-8c57-488b109b696e","world_id":"31740169-035e-5b10-8c9d-98b206e9f24b","slug":"calders-ac6ebc71-dae7-53f1-8c57-488b109b696e","title":"Lantern Row: district","fact_text":"After a difficult night, staff send a plate from the Night Kitchen to the business still closing.","category":"history","truth_mode":"canonical","knowledge_scope":"local","content_level":"standard","location_id":"604a7a05-0d7e-5ea2-9357-1e9953bf3bd1","district_location_id":"604a7a05-0d7e-5ea2-9357-1e9953bf3bd1","topic_tags":["lantern-row","district"],"trigger_terms":["Lantern Row"],"active":true,"metadata":{"source":"calders_run_authoring_v1","authoringFactId":"ac6ebc71-dae7-53f1-8c57-488b109b696e","requiresSavedDisclosure":false,"characterSlugs":[],"revealGate":null,"partialKnowledge":[]}},{"id":"526b3cab-0a7b-517a-bbbd-bf907661ba67","world_id":"31740169-035e-5b10-8c9d-98b206e9f24b","slug":"calders-526b3cab-0a7b-517a-bbbd-bf907661ba67","title":"River Ward: district","fact_text":"The flood erased several streets but not their households. Rebuilt walls contain salvaged material; the headworks and ferry compact are part of family history.","category":"history","truth_mode":"canonical","knowledge_scope":"local","content_level":"standard","location_id":"4331f47a-a84a-5a9c-84bb-29e462d61985","district_location_id":"4331f47a-a84a-5a9c-84bb-29e462d61985","topic_tags":["river-ward","district"],"trigger_terms":["River Ward"],"active":true,"metadata":{"source":"calders_run_authoring_v1","authoringFactId":"526b3cab-0a7b-517a-bbbd-bf907661ba67","requiresSavedDisclosure":false,"characterSlugs":[],"revealGate":null,"partialKnowledge":[]}},{"id":"9c74cce5-c449-5859-aeac-aa2c094f5813","world_id":"31740169-035e-5b10-8c9d-98b206e9f24b","slug":"calders-9c74cce5-c449-5859-aeac-aa2c094f5813","title":"River Ward: district","fact_text":"Early departures, clinic and market business, afternoon repairs, and communal supper create frequent encounters across occupations.","category":"history","truth_mode":"canonical","knowledge_scope":"local","content_level":"standard","location_id":"4331f47a-a84a-5a9c-84bb-29e462d61985","district_location_id":"4331f47a-a84a-5a9c-84bb-29e462d61985","topic_tags":["river-ward","district"],"trigger_terms":["River Ward"],"active":true,"metadata":{"source":"calders_run_authoring_v1","authoringFactId":"9c74cce5-c449-5859-aeac-aa2c094f5813","requiresSavedDisclosure":false,"characterSlugs":[],"revealGate":null,"partialKnowledge":[]}},{"id":"87a14d15-338d-5fbf-965a-43df9a969439","world_id":"31740169-035e-5b10-8c9d-98b206e9f24b","slug":"calders-87a14d15-338d-5fbf-965a-43df9a969439","title":"River Ward: district","fact_text":"People leave dry boards near doors for arrivals with wet boots.","category":"history","truth_mode":"canonical","knowledge_scope":"local","content_level":"standard","location_id":"4331f47a-a84a-5a9c-84bb-29e462d61985","district_location_id":"4331f47a-a84a-5a9c-84bb-29e462d61985","topic_tags":["river-ward","district"],"trigger_terms":["River Ward"],"active":true,"metadata":{"source":"calders_run_authoring_v1","authoringFactId":"87a14d15-338d-5fbf-965a-43df9a969439","requiresSavedDisclosure":false,"characterSlugs":[],"revealGate":null,"partialKnowledge":[]}},{"id":"c8c6b581-3a21-5a22-9116-e5a082343730","world_id":"31740169-035e-5b10-8c9d-98b206e9f24b","slug":"calders-c8c6b581-3a21-5a22-9116-e5a082343730","title":"The Railhead: district","fact_text":"Last year’s survey camp is already a depot, supply street, office compound, and growing settlement. Its residents resent being treated as visitors to the west-bank town.","category":"history","truth_mode":"canonical","knowledge_scope":"local","content_level":"standard","location_id":"b825b72f-5bd8-5f53-a5a3-e4b862932ae7","district_location_id":"b825b72f-5bd8-5f53-a5a3-e4b862932ae7","topic_tags":["the-railhead","district"],"trigger_terms":["The Railhead"],"active":true,"metadata":{"source":"calders_run_authoring_v1","authoringFactId":"c8c6b581-3a21-5a22-9116-e5a082343730","requiresSavedDisclosure":false,"characterSlugs":[],"revealGate":null,"partialKnowledge":[]}},{"id":"6d37f443-dd99-57a2-8d3d-3710492b812a","world_id":"31740169-035e-5b10-8c9d-98b206e9f24b","slug":"calders-6d37f443-dd99-57a2-8d3d-3710492b812a","title":"The Railhead: district","fact_text":"Dispatch and deliveries begin early. Survey and bridge crews move through daylight; correspondence and repairs continue after passenger activity slows.","category":"history","truth_mode":"canonical","knowledge_scope":"local","content_level":"standard","location_id":"b825b72f-5bd8-5f53-a5a3-e4b862932ae7","district_location_id":"b825b72f-5bd8-5f53-a5a3-e4b862932ae7","topic_tags":["the-railhead","district"],"trigger_terms":["The Railhead"],"active":true,"metadata":{"source":"calders_run_authoring_v1","authoringFactId":"6d37f443-dd99-57a2-8d3d-3710492b812a","requiresSavedDisclosure":false,"characterSlugs":[],"revealGate":null,"partialKnowledge":[]}},{"id":"b90696f2-73db-5379-b1be-78dcfdf046db","world_id":"31740169-035e-5b10-8c9d-98b206e9f24b","slug":"calders-b90696f2-73db-5379-b1be-78dcfdf046db","title":"The Railhead: district","fact_text":"The day’s first passenger arrival is checked from the provisioner’s porch with mugs in hand.","category":"history","truth_mode":"canonical","knowledge_scope":"local","content_level":"standard","location_id":"b825b72f-5bd8-5f53-a5a3-e4b862932ae7","district_location_id":"b825b72f-5bd8-5f53-a5a3-e4b862932ae7","topic_tags":["the-railhead","district"],"trigger_terms":["The Railhead"],"active":true,"metadata":{"source":"calders_run_authoring_v1","authoringFactId":"b90696f2-73db-5379-b1be-78dcfdf046db","requiresSavedDisclosure":false,"characterSlugs":[],"revealGate":null,"partialKnowledge":[]}},{"id":"686d57cc-5677-53e4-a103-0a4a2d8780cb","world_id":"31740169-035e-5b10-8c9d-98b206e9f24b","slug":"calders-686d57cc-5677-53e4-a103-0a4a2d8780cb","title":"Cottonwood Valley: district","fact_text":"Several patterns of cultivation precede the modern town. The water register overlays older practices imperfectly, and later ranch consolidation has never settled every claim.","category":"history","truth_mode":"canonical","knowledge_scope":"local","content_level":"standard","location_id":"cff3d4a7-0a30-57e0-ba3f-d74db9b72810","district_location_id":"cff3d4a7-0a30-57e0-ba3f-d74db9b72810","topic_tags":["cottonwood-valley","district"],"trigger_terms":["Cottonwood Valley"],"active":true,"metadata":{"source":"calders_run_authoring_v1","authoringFactId":"686d57cc-5677-53e4-a103-0a4a2d8780cb","requiresSavedDisclosure":false,"characterSlugs":[],"revealGate":null,"partialKnowledge":[]}},{"id":"773f327f-097f-5eb1-86e4-a5b176dc9857","world_id":"31740169-035e-5b10-8c9d-98b206e9f24b","slug":"calders-773f327f-097f-5eb1-86e4-a5b176dc9857","title":"Cottonwood Valley: district","fact_text":"Animals and irrigation require early work; afternoons shift toward repair and household business; evening brings adult lessons, porch visits, and shared meals.","category":"history","truth_mode":"canonical","knowledge_scope":"local","content_level":"standard","location_id":"cff3d4a7-0a30-57e0-ba3f-d74db9b72810","district_location_id":"cff3d4a7-0a30-57e0-ba3f-d74db9b72810","topic_tags":["cottonwood-valley","district"],"trigger_terms":["Cottonwood Valley"],"active":true,"metadata":{"source":"calders_run_authoring_v1","authoringFactId":"773f327f-097f-5eb1-86e4-a5b176dc9857","requiresSavedDisclosure":false,"characterSlugs":[],"revealGate":null,"partialKnowledge":[]}},{"id":"8846869e-e35c-560f-a500-e5b5ce8e53df","world_id":"31740169-035e-5b10-8c9d-98b206e9f24b","slug":"calders-8846869e-e35c-560f-a500-e5b5ce8e53df","title":"Cottonwood Valley: district","fact_text":"At the first cool evening after a hot spell, households bring food to the meeting-house yard.","category":"history","truth_mode":"canonical","knowledge_scope":"local","content_level":"standard","location_id":"cff3d4a7-0a30-57e0-ba3f-d74db9b72810","district_location_id":"cff3d4a7-0a30-57e0-ba3f-d74db9b72810","topic_tags":["cottonwood-valley","district"],"trigger_terms":["Cottonwood Valley"],"active":true,"metadata":{"source":"calders_run_authoring_v1","authoringFactId":"8846869e-e35c-560f-a500-e5b5ce8e53df","requiresSavedDisclosure":false,"characterSlugs":[],"revealGate":null,"partialKnowledge":[]}},{"id":"1277dd0b-aa1a-59e1-bf11-acc4f382f694","world_id":"31740169-035e-5b10-8c9d-98b206e9f24b","slug":"calders-1277dd0b-aa1a-59e1-bf11-acc4f382f694","title":"Cinder Bluffs: district","fact_text":"Commercial silver connected scattered routes and camps. The 1881 collapse left a mutual society, a cemetery expansion, and unresolved arguments about responsibility.","category":"history","truth_mode":"canonical","knowledge_scope":"local","content_level":"standard","location_id":"4aa276e2-1323-53a9-b9eb-d8de7cf3547e","district_location_id":"4aa276e2-1323-53a9-b9eb-d8de7cf3547e","topic_tags":["cinder-bluffs","district"],"trigger_terms":["Cinder Bluffs"],"active":true,"metadata":{"source":"calders_run_authoring_v1","authoringFactId":"1277dd0b-aa1a-59e1-bf11-acc4f382f694","requiresSavedDisclosure":false,"characterSlugs":[],"revealGate":null,"partialKnowledge":[]}},{"id":"394acae2-4e65-503a-ab73-fa4c2a01409f","world_id":"31740169-035e-5b10-8c9d-98b206e9f24b","slug":"calders-394acae2-4e65-503a-ab73-fa4c2a01409f","title":"Cinder Bluffs: district","fact_text":"Mining and travel start early. Supply exchanges fill midday; late arrivals gather at stations and trading rooms before the roads become difficult.","category":"history","truth_mode":"canonical","knowledge_scope":"local","content_level":"standard","location_id":"4aa276e2-1323-53a9-b9eb-d8de7cf3547e","district_location_id":"4aa276e2-1323-53a9-b9eb-d8de7cf3547e","topic_tags":["cinder-bluffs","district"],"trigger_terms":["Cinder Bluffs"],"active":true,"metadata":{"source":"calders_run_authoring_v1","authoringFactId":"394acae2-4e65-503a-ab73-fa4c2a01409f","requiresSavedDisclosure":false,"characterSlugs":[],"revealGate":null,"partialKnowledge":[]}},{"id":"4f034df6-324e-5e8f-b6b4-0d1552bbb6cc","world_id":"31740169-035e-5b10-8c9d-98b206e9f24b","slug":"calders-4f034df6-324e-5e8f-b6b4-0d1552bbb6cc","title":"Cinder Bluffs: district","fact_text":"A returned traveler is offered water before being asked for news.","category":"history","truth_mode":"canonical","knowledge_scope":"local","content_level":"standard","location_id":"4aa276e2-1323-53a9-b9eb-d8de7cf3547e","district_location_id":"4aa276e2-1323-53a9-b9eb-d8de7cf3547e","topic_tags":["cinder-bluffs","district"],"trigger_terms":["Cinder Bluffs"],"active":true,"metadata":{"source":"calders_run_authoring_v1","authoringFactId":"4f034df6-324e-5e8f-b6b4-0d1552bbb6cc","requiresSavedDisclosure":false,"characterSlugs":[],"revealGate":null,"partialKnowledge":[]}},{"id":"a6cc58aa-d78e-58fa-a768-69f2f8fdc2ec","world_id":"31740169-035e-5b10-8c9d-98b206e9f24b","slug":"calders-a6cc58aa-d78e-58fa-a768-69f2f8fdc2ec","title":"Calder''s Run: history","fact_text":"Before 1859 — Routes before the town: Indigenous movement, older Mexican households, small-scale cultivation, and local irrigation precede the freight settlement. Specific communities have continuing interests; the river is not empty land awaiting discovery.","category":"local_knowledge","truth_mode":"canonical","knowledge_scope":"local","content_level":"standard","location_id":null,"district_location_id":null,"topic_tags":["calders-run","history"],"trigger_terms":["Calder''s Run"],"active":true,"metadata":{"source":"calders_run_authoring_v1","authoringFactId":"a6cc58aa-d78e-58fa-a768-69f2f8fdc2ec","requiresSavedDisclosure":false,"characterSlugs":[],"revealGate":null,"partialKnowledge":[]}},{"id":"20cfc3f6-3f28-52c2-a243-9e7c14a83256","world_id":"31740169-035e-5b10-8c9d-98b206e9f24b","slug":"calders-20cfc3f6-3f28-52c2-a243-9e7c14a83256","title":"Calder''s Run: history","fact_text":"1859 — Calder’s Run: Amelia Calder organizes a reliable freight-and-ferry circuit. The route lends its name to the settlement; the ferry book begins as a practical business record.","category":"local_knowledge","truth_mode":"canonical","knowledge_scope":"local","content_level":"standard","location_id":null,"district_location_id":null,"topic_tags":["calders-run","history"],"trigger_terms":["Calder''s Run"],"active":true,"metadata":{"source":"calders_run_authoring_v1","authoringFactId":"20cfc3f6-3f28-52c2-a243-9e7c14a83256","requiresSavedDisclosure":false,"characterSlugs":[],"revealGate":null,"partialKnowledge":[]}},{"id":"f6346a01-c06e-52b1-8432-2d9cd626f2fa","world_id":"31740169-035e-5b10-8c9d-98b206e9f24b","slug":"calders-f6346a01-c06e-52b1-8432-2d9cd626f2fa","title":"Calder''s Run: history","fact_text":"1864 — Silver in the bluffs: Commercial workings expand at what becomes Saint Agnes. Supply yards and modest lodging follow the workers.","category":"local_knowledge","truth_mode":"canonical","knowledge_scope":"local","content_level":"standard","location_id":null,"district_location_id":null,"topic_tags":["calders-run","history"],"trigger_terms":["Calder''s Run"],"active":true,"metadata":{"source":"calders_run_authoring_v1","authoringFactId":"f6346a01-c06e-52b1-8432-2d9cd626f2fa","requiresSavedDisclosure":false,"characterSlugs":[],"revealGate":null,"partialKnowledge":[]}},{"id":"b9408089-3a6b-517a-af01-1d8911c82cfa","world_id":"31740169-035e-5b10-8c9d-98b206e9f24b","slug":"calders-b9408089-3a6b-517a-af01-1d8911c82cfa","title":"Calder''s Run: history","fact_text":"1868 — A permanent Main Street: Brick businesses replace several temporary fronts. A public reading room becomes the first court-record office.","category":"local_knowledge","truth_mode":"canonical","knowledge_scope":"local","content_level":"standard","location_id":null,"district_location_id":null,"topic_tags":["calders-run","history"],"trigger_terms":["Calder''s Run"],"active":true,"metadata":{"source":"calders_run_authoring_v1","authoringFactId":"b9408089-3a6b-517a-af01-1d8911c82cfa","requiresSavedDisclosure":false,"characterSlugs":[],"revealGate":null,"partialKnowledge":[]}},{"id":"ba9bebc1-5052-5827-a642-97c485794850","world_id":"31740169-035e-5b10-8c9d-98b206e9f24b","slug":"calders-ba9bebc1-5052-5827-a642-97c485794850","title":"Calder''s Run: history","fact_text":"1872 — The high-water year: Flooding damages River Ward and destroys a portion of county records. Collective rebuilding creates both solidarity and disputed obligations.","category":"local_knowledge","truth_mode":"canonical","knowledge_scope":"local","content_level":"standard","location_id":null,"district_location_id":null,"topic_tags":["calders-run","history"],"trigger_terms":["Calder''s Run"],"active":true,"metadata":{"source":"calders_run_authoring_v1","authoringFactId":"ba9bebc1-5052-5827-a642-97c485794850","requiresSavedDisclosure":false,"characterSlugs":[],"revealGate":null,"partialKnowledge":[]}},{"id":"96c6998f-d390-57da-b930-7f9cebd58831","world_id":"31740169-035e-5b10-8c9d-98b206e9f24b","slug":"calders-96c6998f-d390-57da-b930-7f9cebd58831","title":"Calder''s Run: history","fact_text":"1874 — The crossing compact: A local trusteeship formalizes ferry maintenance, public headworks, and registered water turns. Emergency advantages become durable privileges.","category":"local_knowledge","truth_mode":"canonical","knowledge_scope":"local","content_level":"standard","location_id":null,"d